param(
  [ValidateSet("payg", "token-plan")]
  [string]$Mode = "payg",

  [string]$BaseUrl,

  [string]$Model = "mimo-v2.5-pro"
)

$ErrorActionPreference = "Stop"

function Get-JsonObjectOrDefault {
  param(
    [Parameter(Mandatory = $true)]
    [string]$Path,

    [Parameter(Mandatory = $true)]
    [hashtable]$DefaultObject
  )

  if (-not (Test-Path $Path)) {
    return $DefaultObject
  }

  try {
    $parsed = Get-Content $Path -Raw | ConvertFrom-Json
    $result = [ordered]@{}
    foreach ($prop in $parsed.PSObject.Properties) {
      $result[$prop.Name] = $prop.Value
    }
    return $result
  } catch {
    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
    Copy-Item $Path "$Path.invalid-$timestamp"
    return $DefaultObject
  }
}

if (-not $BaseUrl) {
  if ($Mode -eq "token-plan") {
    $BaseUrl = "https://token-plan-cn.xiaomimimo.com/anthropic"
  } else {
    $BaseUrl = "https://api.xiaomimimo.com/anthropic"
  }
}

$apiKey = Read-Host "Enter Xiaomi MiMo API Key (input is hidden)" -AsSecureString
$bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($apiKey)
try {
  $plainApiKey = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)
} finally {
  [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
}

if ([string]::IsNullOrWhiteSpace($plainApiKey)) {
  throw "API Key is required."
}

$claudeDir = Join-Path $HOME ".claude"
$settingsPath = Join-Path $claudeDir "settings.json"

